#include <bits/stdc++.h>
using namespace std;

struct Arc {
  int s, d;
  double w;
  Arc(int u, int v, double cap) : s(u), d(v), w(cap) {}
};

struct Node {
  vector<int> adj;
};

struct MaxFlowGraph {
  vector<Node> V;
  vector<Arc> E;

  MaxFlowGraph(int nodes, int edges_cap) : V(nodes), E() {
    E.reserve(edges_cap);
  }

  void link(int u, int v, double cap) {
    E.emplace_back(u, v, cap);
    V[u].adj.push_back(int(E.size()) - 1);
  }

  vector<int> dfs_path(int src, int dst, vector<double>& f, double* bneck) {
    using state = pair<double, int>;
    set<state, greater<state>> pq;
    vector<double> dist(V.size(), 0.0);
    vector<int> prev_edge(V.size(), -1);

    dist[src] = numeric_limits<double>::max();
    pq.emplace(dist[src], src);

    while (!pq.empty() && dist[dst] == 0.0) {
      auto [cap, node] = *pq.begin();
      pq.erase(pq.begin());

      for (int idx : V[node].adj) {
        const Arc& a = E[idx];
        double res = a.w - f[idx];
        if (res > 0) {
          double nc = min(cap, res);
          if (nc > dist[a.d]) {
            auto it = pq.find({dist[a.d], a.d});
            if (it != pq.end()) pq.erase(it);
            dist[a.d] = nc;
            pq.emplace(dist[a.d], a.d);
            prev_edge[a.d] = idx;
          }
        }
      }
    }

    *bneck = dist[dst];
    vector<int> path;
    for (int e = prev_edge[dst]; e != -1; e = prev_edge[E[e].s])
      path.push_back(e);
    return path;
  }

  double compute_flow(int s, int t) {
    MaxFlowGraph residual(V.size(), int(E.size()) * 2);
    vector<double> flow(2 * E.size(), 0.0);

    for (size_t i = 0; i < E.size(); ++i) {
      residual.link(E[i].s, E[i].d, E[i].w);
      residual.link(E[i].d, E[i].s, 0.0);
    }

    double total = 0.0;
    double cap;
    for (auto path = residual.dfs_path(s, t, flow, &cap);
         !path.empty() && cap > 0;
         path = residual.dfs_path(s, t, flow, &cap)) {
      for (int e : path) {
        int rev = (e % 2) ? e - 1 : e + 1;
        flow[e] += cap;
        flow[rev] -= cap;
      }
      total += cap;
    }

    for (int idx : residual.V[s].adj)
      total += flow[idx];
    return total;
  }
};

int n, T;
struct Cell {
  int r, c;
  array<bool, 61> sick{};
  array<bool, 61> accessible{};
  int people{}, pods{};

  Cell() : people(0), pods(0) { fill(accessible.begin(), accessible.end(), true); }

  int vertex_id(int t) const { return 2 + r + n*c + n*n*t; }

  void block() { fill(accessible.begin(), accessible.end(), false); }

  void infect(int t = 0) {
    if (accessible[t]) {
      accessible[t] = false;
      sick[t] = true;
    }
  }

  void spread(int t);
};

Cell world[10][10];

void Cell::spread(int t) {
  if (sick[t]) {
    infect(t + 1);
    if (r > 0) world[r-1][c].infect(t + 1);
    if (r < n - 1) world[r+1][c].infect(t + 1);
    if (c > 0) world[r][c-1].infect(t + 1);
    if (c < n - 1) world[r][c+1].infect(t + 1);
  }
}

string vertex_label(int id) {
  if (id == 0) return "source";
  if (id == 1) return "sink";
  ostringstream oss;
  int row = (id - 2) % n;
  int col = ((id - 2 - row) % (n*n)) / n;
  int time = (id - 2 - row - col*n) / (n*n);
  oss << "(" << row << "," << col << "," << time << ")";
  return oss.str();
}

int main() {
  ios::sync_with_stdio(false);
  cin >> n >> T;

  for (int i = 0; i < n; ++i) {
    string line;
    cin >> line;
    for (int j = 0; j < n; ++j) {
      world[i][j].r = i;
      world[i][j].c = j;
      if (line[j] == 'Y') world[i][j].block();
      else if (line[j] == 'Z') world[i][j].infect();
      else world[i][j].people = line[j] - '0';
    }
  }

  for (int i = 0; i < n; ++i) {
    string line;
    cin >> line;
    for (int j = 0; j < n; ++j) {
      if (line[j] != 'Y' && line[j] != 'Z')
        world[i][j].pods = line[j] - '0';
    }
  }

  for (int step = 0; step <= T; ++step)
    for (int i = 0; i < n; ++i)
      for (int j = 0; j < n; ++j)
        if (step < T) world[i][j].spread(step);

  MaxFlowGraph g(n*n*(T+1)+2, 100*4*60);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) {
      const Cell& cell = world[i][j];
      if (cell.people > 0) g.link(0, cell.vertex_id(0), cell.people);
      if (cell.pods > 0) g.link(cell.vertex_id(T), 1, cell.pods);
      for (int step = 0; step < T; ++step) {
        if (cell.pods > 0) g.link(cell.vertex_id(step), cell.vertex_id(T), 1000);
        if (cell.accessible[step]) {
          if (i > 0 && world[i-1][j].accessible[step])
            g.link(cell.vertex_id(step), world[i-1][j].vertex_id(step+1), 1000);
          if (i < n-1 && world[i+1][j].accessible[step])
            g.link(cell.vertex_id(step), world[i+1][j].vertex_id(step+1), 1000);
          if (j > 0 && world[i][j-1].accessible[step])
            g.link(cell.vertex_id(step), world[i][j-1].vertex_id(step+1), 1000);
          if (j < n-1 && world[i][j+1].accessible[step])
            g.link(cell.vertex_id(step), world[i][j+1].vertex_id(step+1), 1000);
        }
      }
    }

  cout << int(g.compute_flow(0, 1)) << '\n';
  return 0;
}
